{"path":"services.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Sessions — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#0f1720;--card:#0f1a24;--accent:#a6d2c1;--muted:#9aa6b2;--glass:rgba(255,255,255,0.04);--mono: #cbd5e1}
    html,body{height:100%;margin:0;font-family:Inter,system-ui,-apple-system,Segoe UI,Roboto,'Helvetica Neue',Arial;color:var(--mono);background:linear-gradient(180deg,#071018 0%, #071b22 50%);}
    header{display:flex;align-items:center;justify-content:space-between;padding:22px 28px;background:linear-gradient(90deg,rgba(255,255,255,0.02),transparent);backdrop-filter:blur(6px)}
    .brand{display:flex;gap:14px;align-items:center}
    .logo{width:48px;height:48px;border-radius:10px;background:linear-gradient(135deg,var(--accent),#6fb39b);display:flex;align-items:center;justify-content:center;font-weight:700;color:#072;box-shadow:0 6px 18px rgba(0,0,0,0.45)}
    nav a{color:var(--mono);text-decoration:none;margin-left:18px;font-weight:600}
    .wrap{max-width:1080px;margin:32px auto;padding:24px}
    .grid{display:grid;grid-template-columns:1fr 420px;gap:22px}
    .hero{background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);padding:28px;border-radius:12px;box-shadow:inset 0 1px 0 rgba(255,255,255,0.02)}
    h1{margin:0 0 8px 0;color:#e8f7f0;font-size:28px}
    p.lead{margin:0;color:var(--muted)}
    .card{background:var(--card);padding:18px;border-radius:12px}
    label{display:block;margin-top:12px;color:var(--muted);font-size:13px}
    input[type=text],select,textarea{width:100%;padding:10px;border-radius:8px;border:1px solid rgba(255,255,255,0.04);background:var(--glass);color:var(--mono);margin-top:6px}
    .btn{display:inline-block;padding:10px 14px;border-radius:10px;background:linear-gradient(90deg,var(--accent),#79bd9a);color:#05211a;font-weight:700;border:none;cursor:pointer}
    .muted{color:var(--muted);font-size:13px}
    .list{display:flex;flex-direction:column;gap:10px;margin-top:14px}
    .pill{display:inline-block;padding:6px 10px;border-radius:999px;background:rgba(255,255,255,0.02);border:1px solid rgba(255,255,255,0.02)}
    pre{white-space:pre-wrap;background:rgba(2,6,23,0.6);padding:12px;border-radius:8px;color:var(--mono);font-size:13px}
    footer{padding:30px;text-align:center;color:var(--muted);font-size:13px}
    .note{font-size:12px;color:#bcd6cc;margin-top:8px}
    .small-cta{margin-top:14px}
    @media(max-width:900px){.grid{grid-template-columns:1fr;}.brand .logo{width:40px;height:40px}}
  </style>
</head>
<body>
  <header>
    <div class="brand">
      <div class="logo">A</div>
      <div>
        <div style="font-weight:800">{{BUSINESS_NAME}}</div>
        <div style="font-size:12px;color:var(--muted)">{{TAGLINE}}</div>
      </div>
    </div>
    <nav>
      <a href="index.html">Home</a>
      <a href="services.html">Sessions</a>
      <a href="blends.html">Concoctions</a>
      <a href="shop.html">Apothecary</a>
      <a href="pricing.html">Fees</a>
      <a href="book.html">Reserve</a>
      <a href="contact.html">Connect</a>
    </nav>
  </header>

  <main class="wrap">
    <div class="grid">
      <section class="hero">
        <h1>Personal Session Planner</h1>
        <p class="lead">Build a thoughtful scent rhythm for the weeks ahead. No medical promises — choices that may support calm, clarity, or restful evenings.</p>
        <div style="margin-top:18px" class="card">
          <form id="planner">
            <label>Primary intention</label>
            <input type="text" id="intention" placeholder="e.g., steady energy during work, unwind before sleep">

            <label>Focus areas (choose up to 3)</label>
            <div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:6px">
              <button type="button" class="pill" data-val="calm">Calm</button>
              <button type="button" class="pill" data-val="focus">Focus</button>
              <button type="button" class="pill" data-val="sleep">Sleep</button>
              <button type="button" class="pill" data-val="uplift">Uplift</button>
              <button type="button" class="pill" data-val="ground">Grounding</button>
            </div>

            <label>Session rhythm</label>
            <select id="frequency">
              <option value="daily">Daily micro-practice</option>
              <option value="3x">3x per week</option>
              <option value="weekly">Weekly focus session</option>
              <option value="intensive">Two-week intensive</option>
            </select>

            <label>Preferred scent families</label>
            <div style="display:flex;gap:8px;margin-top:8px">
              <label class="muted"><input type="checkbox" value="floral"> Floral</label>
              <label class="muted"><input type="checkbox" value="herbal"> Herbal</label>
              <label class="muted"><input type="checkbox" value="citrus"> Citrus</label>
              <label class="muted"><input type="checkbox" value="woody"> Woody</label>
            </div>

            <label style="margin-top:12px">Session length</label>
            <select id="length">
              <option value="5">5 minutes (micro)</option>
              <option value="15">15 minutes</option>
              <option value="40">40 minutes (session)</option>
            </select>

            <div style="display:flex;gap:10px;margin-top:16px;align-items:center">
              <button class="btn" id="build">Create Plan</button>
              <div class="small-cta muted">We’ll generate clear steps and a simple at-home ritual you can copy.</div>
            </div>
          </form>

          <div id="result" style="display:none;margin-top:14px">
            <h3 style="margin:0;color:var(--accent)">Your Plan</h3>
            <pre id="planout">...</pre>
            <div style="display:flex;gap:10px;margin-top:8px">
              <button class="btn" id="copyPlan">Copy Summary</button>
              <button class="btn" id="emailPlan" style="background:transparent;color:var(--accent);border:1px solid rgba(255,255,255,0.04)">Email Plan</button>
            </div>
            <div class="note">Safety: always test a new scent on a small skin area. If pregnant, nursing, or living with pets, review the safety notes below or consult a qualified practitioner.</div>
          </div>
        </div>

        <div style="margin-top:18px;color:var(--muted);font-size:13px">
          <strong>How it works</strong>
          <p class="muted">We shape a short ritual and a scent suggestion that may support your stated intention. This planner is for guidance and personal use only.</p>
        </div>
      </section>

      <aside>
        <div class="card">
          <h3 style="margin-top:0">Session offerings</h3>
          <div style="display:flex;flex-direction:column;gap:12px;margin-top:8px">
            <div>
              <div style="font-weight:700">Focus Lab — 40 min</div>
              <div class="muted">Gentle scent layering to support short, clear work spans. Includes take-home micro-practice.</div>
            </div>
            <div>
              <div style="font-weight:700">Ground & Reset — 60 min</div>
              <div class="muted">More exploration and breath-guided scenting for deeper settling.</div>
            </div>
            <div>
              <div style="font-weight:700">Intensive Pathway — 4 sessions</div>
              <div class="muted">A short course for moment-to-moment habit formation and a bespoke blend card.</div>
            </div>
          </div>
          <div style="margin-top:12px"><a href="book.html" class="btn">Reserve a slot</a></div>
        </div>

        <div class="card" style="margin-top:14px">
          <h4 style="margin:0">Quick safety notes</h4>
          <ul class="muted" style="margin-top:8px">
            <li>Start with low dilutions (0.5–2%).</li>
            <li>Always patch-test on the inner forearm before topical use.</li>
            <li>Essential oils should be kept away from eyes and mucous membranes.</li>
            <li>If pregnant or nursing, consult with your health care provider about specific oils.</li>
            <li>Some oils can be hazardous to pets — review notes before use around animals.</li>
          </ul>
        </div>
      </aside>
    </div>

    <section style="margin-top:20px" class="card">
      <h3 style="margin:0 0 8px 0">Plan history</h3>
      <div class="muted">Plans you build here are stored locally in your browser. Use the copy button to export a plaintext summary to share.</div>
    </section>

  </main>

  <footer>
    <div>{{BUSINESS_NAME}} — Serving {{CITY}}, {{STATE}} • <a href="tel:{{PHONE}}" style="color:var(--accent);text-decoration:none">{{PHONE}}</a> • <a href="mailto:{{EMAIL}}" style="color:var(--accent);text-decoration:none">{{EMAIL}}</a></div>
  </footer>

  <script>
    (function(){
      const pillButtons = document.querySelectorAll('.pill');
      const selected = new Set();
      pillButtons.forEach(b=>b.addEventListener('click',()=>{
        const v=b.getAttribute('data-val');
        if(selected.has(v)){ selected.delete(v); b.style.opacity='1'; b.style.border='1px solid rgba(255,255,255,0.02)'; }
        else if(selected.size<3){ selected.add(v); b.style.opacity='0.8'; b.style.border='1px solid rgba(255,255,255,0.08)'; }
      }));

      document.getElementById('planner').addEventListener('submit',function(e){
        e.preventDefault();
        const intention = document.getElementById('intention').value.trim() || 'Personal intention';
        const freq = document.getElementById('frequency').value;
        const len = document.getElementById('length').value;
        const checked = Array.from(document.querySelectorAll('input[type=checkbox]:checked')).map(i=>i.value);
        const vibe = Array.from(selected).join(', ') || 'balanced';

        // Build a simple plan
        const steps = [];
        steps.push('Intention: '+intention);
        steps.push('Primary vibe: '+vibe);
        steps.push('Scent families: '+(checked.length?checked.join(', '):'neutral')); 
        steps.push('Rhythm: '+(freq==='daily'? 'Every day — a short micro-practice':'See schedule: '+freq));
        steps.push('Typical session length: '+len+' minutes');

        // Small ritual suggestion
        if(freq==='daily') steps.push('Ritual: 3 deep breaths with diffuser or inhaler; 1–2 drops in palms for 30s mindful inhale.');
        else if(freq==='3x') steps.push('Ritual: Prepare blend on session days; inhale once before work and once mid-day.');
        else if(freq==='weekly') steps.push('Ritual: Create a longer ritual with journaling and a 15-minute scented pause.');
        else steps.push('Ritual: Intensive check-ins and a curated at-home blend card for daily use.');

        steps.push('Safety note: Start at 0.5–2% dilution for topical blends; patch test before skin contact. Avoid eyes and mucous membranes.');
        steps.push('If pregnant, nursing, or living with pets, consult safety notes before use.');

        const output = steps.join('\n\n');
        document.getElementById('planout').textContent = output;
        document.getElementById('result').style.display='block';
      });

      document.getElementById('copyPlan').addEventListener('click',async()=>{
        const text = document.getElementById('planout').textContent;
        try{ await navigator.clipboard.writeText(text); alert('Plan copied to clipboard'); }
        catch(e){ prompt('Copy the plan text below', text); }
      });

      document.getElementById('emailPlan').addEventListener('click',()=>{
        const text = encodeURIComponent(document.getElementById('planout').textContent);
        window.location.href = 'mailto:'+encodeURIComponent('{{EMAIL}}')+'?subject='+encodeURIComponent('My Scent Plan')+'&body='+text;
      });

    })();
  </script>
</body>
</html>"} 
{"path":"blends.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Concoctions — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#071521;--card:#0b1a1f;--accent:#ffd8b1;--muted:#9fb2b3;--ink:#f7f7f6}
    body{margin:0;font-family:Inter,system-ui,Segoe UI,Roboto,Arial;background:var(--bg);color:var(--ink)}
    header{display:flex;justify-content:space-between;align-items:center;padding:18px 26px;background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent)}
    .logo{width:46px;height:46px;border-radius:10px;background:linear-gradient(135deg,#f6b185,#ffd8b1);display:flex;align-items:center;justify-content:center;font-weight:800;color:#2b1a0f}
    nav a{color:var(--ink);text-decoration:none;margin-left:16px;font-weight:600}
    .wrap{max-width:1040px;margin:28px auto;padding:20px}
    .hero{padding:22px;border-radius:12px;background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);display:flex;gap:18px}
    .left{flex:1}
    .right{width:380px}
    .card{background:var(--card);padding:18px;border-radius:12px}
    select,input{width:100%;padding:10px;border-radius:8px;border:1px solid rgba(255,255,255,0.03);background:transparent;color:var(--ink);margin-top:8px}
    .btn{padding:10px 14px;border-radius:10px;background:linear-gradient(90deg,#ffd8b1,#ffb08a);color:#2b1a0f;border:none;cursor:pointer;font-weight:700}
    .mini{font-size:13px;color:var(--muted)}
    pre{white-space:pre-wrap;background:rgba(0,0,0,0.25);padding:12px;border-radius:8px}
    .palette{display:flex;gap:8px;flex-wrap:wrap;margin-top:10px}
    .sw{padding:8px 12px;border-radius:8px;background:rgba(255,255,255,0.02);cursor:pointer}
    footer{padding:30px;text-align:center;color:var(--muted)}
  </style>
</head>
<body>
  <header>
    <div style="display:flex;align-items:center;gap:12px">
      <div class="logo">C</div>
      <div>
        <div style="font-weight:800">{{BUSINESS_NAME}}</div>
        <div style="font-size:12px;color:var(--muted)">Concoctions & recipes</div>
      </div>
    </div>
    <nav>
      <a href="index.html">Home</a>
      <a href="services.html">Sessions</a>
      <a href="blends.html">Concoctions</a>
      <a href="shop.html">Apothecary</a>
      <a href="about.html">About</a>
    </nav>
  </header>

  <main class="wrap">
    <div class="hero">
      <div class="left card">
        <h2 style="margin:0 0 6px 0;color:var(--accent)">Blend Builder</h2>
        <p class="mini">Choose a mood, select a bottle size and carrier, and we’ll make a safe dilution recommendation plus a printable blend card. This is non-medical guidance.</p>

        <label style="margin-top:12px">Mood / Vibe</label>
        <div class="palette">
          <div class="sw" data-vibe="calm">Calm</div>
          <div class="sw" data-vibe="energize">Energize</div>
          <div class="sw" data-vibe="focus">Focus</div>
          <div class="sw" data-vibe="sleep">Sleep</div>
          <div class="sw" data-vibe="ground">Ground</div>
        </div>

        <label>Bottle size</label>
        <select id="bottle">
          <option value="5">5 mL</option>
          <option value="10" selected>10 mL</option>
          <option value="30">30 mL</option>
        </select>

        <label>Carrier oil</label>
        <select id="carrier">
          <option value="jojoba">Jojoba</option>
          <option value="sweet_almond">Sweet Almond</option>
          <option value="fractionated_coconut">Fractionated Coconut</option>
        </select>

        <label>Target dilution</label>
        <select id="dilution">
          <option value="0.5">0.5% — sensitive</option>
          <option value="1">1% — daily wear</option>
          <option value="2" selected>2% — noticeable effect</option>
        </select>

        <div style="display:flex;gap:10px;margin-top:12px">
          <button class="btn" id="make">Create Blend Card</button>
          <button class="btn" id="clear" style="background:transparent;border:1px solid rgba(255,255,255,0.04);color:var(--ink)">Reset</button>
        </div>

        <div style="margin-top:12px" class="mini">Tip: Citrus oils can increase photosensitivity. Use low dilutions and avoid direct sunlight on skin after topical application.</div>
      </div>

      <aside class="right card">
        <h3 style="margin-top:0">Preview</h3>
        <div id="cardArea">
          <div class="mini">No blend yet. Pick a vibe to begin.</div>
        </div>
        <div style="margin-top:12px">
          <button class="btn" id="copyCard">Copy Card</button>
        </div>

        <div style="margin-top:14px" class="mini">
          <strong>Safety highlights</strong>
          <ul>
            <li>Patch test before topical use.</li>
            <li>Keep away from eyes and mucous membranes.</li>
            <li>If pregnant/nursing or caring for pets, check the specific oil guidance below.</li>
          </ul>
        </div>
      </aside>
    </div>

    <section style="margin-top:18px" class="card">
      <h3 style="margin:0 0 8px 0">About the dilution guide</h3>
      <p class="mini">We calculate drops using ~20 drops per mL. The guide will show how many drops of essential oil to add to your chosen bottle size for the dilution you selected. These are conservative numbers meant for safe topical and inhalation use for most adults.</p>
    </section>

    <section style="margin-top:18px" class="card">
      <h3 style="margin:0 0 8px 0">Frequently asked safety questions</h3>
      <div class="mini">
        <strong>Patch test</strong>
        <p>Apply a small, diluted amount to inner forearm. Wait 24 hours. If irritation occurs, discontinue use.</p>
        <strong>Pregnancy & nursing</strong>
        <p>Some oils are not recommended. Please consult your healthcare provider before use.</p>
        <strong>Pets</strong>
        <p>Certain oils (e.g., tea tree, citrus in high amounts) can be harmful to small animals. Avoid topical or diffused exposure around sensitive pets without vet advice.</p>
      </div>
    </section>

  </main>

  <footer>
    <div>{{BUSINESS_NAME}} • <a href="mailto:{{EMAIL}}" style="color:var(--accent);text-decoration:none">{{EMAIL}}</a> • Serving {{CITY}}, {{STATE}}</div>
  </footer>

  <script>
    (function(){
      const vibes = {
        calm: {name:'Calm', oils:[{n:'Lavender',r:'floral'},{n:'Sweet marjoram',r:'herbal'},{n:'Frankincense',r:'woody'}]},
        energize: {name:'Energize', oils:[{n:'Sweet orange',r:'citrus'},{n:'Grapefruit',r:'citrus'},{n:'Peppermint',r:'herbal'}]},
        focus: {name:'Focus', oils:[{n:'Rosemary',r:'herbal'},{n:'Basil',r:'herbal'},{n:'Cedarwood',r:'woody'}]},
        sleep: {name:'Sleep', oils:[{n:'Chamomile',r:'floral'},{n:'Lavender',r:'floral'},{n:'Vetiver',r:'woody'}]},
        ground: {name:'Ground', oils:[{n:'Patchouli',r:'woody'},{n:'Cedarwood',r:'woody'},{n:'Bergamot',r:'citrus'}]}
      };

      function dropsFor(bottleMl){ return Math.round(bottleMl*20); }
      function computeDrops(totalDrops,percent){ return Math.max(1,Math.round(totalDrops*(percent/100))); }

      document.querySelectorAll('.sw').forEach(el=>el.addEventListener('click',()=>{
        document.querySelectorAll('.sw').forEach(s=>s.style.outline=''); el.style.outline='2px solid rgba(255,216,177,0.25)'; el.setAttribute('data-selected','1');
      }));

      document.getElementById('make').addEventListener('click',()=>{
        const selected = document.querySelector('.sw[data-selected="1"]');
        if(!selected){ alert('Choose a vibe first'); return; }
        const vibeKey = selected.getAttribute('data-vibe');
        const vibe = vibes[vibeKey];
        const bottle = Number(document.getElementById('bottle').value);
        const carrier = document.getElementById('carrier').value.replace('_',' ');
        const dil = Number(document.getElementById('dilution').value);

        const totalDrops = dropsFor(bottle);
        const eoDrops = computeDrops(totalDrops,dil);
        const perOil = Math.max(1, Math.round(eoDrops / vibe.oils.length));

        const card = [];
        card.push('Blend: '+vibe.name);
        card.push('Bottle: '+bottle+' mL ('+totalDrops+' drops)');
        card.push('Carrier: '+carrier);
        card.push('Target dilution: '+(dil)+'%');
        card.push('Total essential oil drops: '+eoDrops);
        card.push('Suggested oils and drops:');
        vibe.oils.forEach((o,i)=> card.push('- '+o.n+' — '+perOil+' drops'));
        card.push('Method: Add essential oil drops to carrier in bottle, shake gently before use. For inhalation, add 1–2 drops to a tissue or inhaler.');
        card.push('Safety: Patch test on inner forearm. Avoid eyes. If pregnant, nursing, or around pets, review oil-specific guidance.');

        document.getElementById('cardArea').innerHTML = '<pre>'+card.join('\n')+'</pre>';
      });

      document.getElementById('clear').addEventListener('click',()=>{
        document.querySelectorAll('.sw').forEach(s=>{s.style.outline='';s.removeAttribute('data-selected')});
        document.getElementById('cardArea').innerHTML = '<div class="mini">No blend yet. Pick a vibe to begin.</div>';
      });

      document.getElementById('copyCard').addEventListener('click',async()=>{
        const pre = document.querySelector('#cardArea pre');
        if(!pre){ alert('No blend to copy'); return; }
        const text = pre.textContent;
        try{ await navigator.clipboard.writeText(text); alert('Blend card copied'); }
        catch(e){ prompt('Copy this blend card', text); }
      });

    })();
  </script>
</body>
</html>"} 
{"path":"shop.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Apothecary — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#081218;--panel:#0b1720;--accent:#9ad3c4;--muted:#a7b7bd}
    body{margin:0;font-family:Inter,system-ui,Segoe UI,Roboto,Arial;background:var(--bg);color:#eaf6f0}
    header{display:flex;justify-content:space-between;align-items:center;padding:18px 22px;background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent)}
    .logo{width:46px;height:46px;border-radius:10px;background:linear-gradient(135deg,#9ad3c4,#6fb39b);display:flex;align-items:center;justify-content:center;font-weight:800;color:#062018}
    nav a{color:var(--muted);text-decoration:none;margin-left:14px;font-weight:600}
    .wrap{max-width:1100px;margin:28px auto;padding:20px}
    .grid{display:grid;grid-template-columns:1fr 320px;gap:18px}
    .catalog{display:grid;grid-template-columns:repeat(2,1fr);gap:12px}
    .prod{background:var(--panel);padding:14px;border-radius:10px}
    .btn{padding:9px 12px;border-radius:10px;background:var(--accent);color:#053226;border:none;cursor:pointer;font-weight:700}
    .muted{color:var(--muted);font-size:13px}
    .mini{font-size:13px;color:var(--muted)}
    footer{padding:28px;text-align:center;color:var(--muted)}
    @media(max-width:900px){.grid{grid-template-columns:1fr}.catalog{grid-template-columns:1fr}}
  </style>
</head>
<body>
  <header>
    <div style="display:flex;gap:12px;align-items:center">
      <div class="logo">{{BUSINESS_NAME}}'.charAt(0)</div>
      <div>
        <div style="font-weight:800">{{BUSINESS_NAME}}</div>
        <div style="font-size:12px;color:var(--muted)">Apothecary & supplies</div>
      </div>
    </div>
    <nav>
      <a href="index.html">Home</a>
      <a href="services.html">Sessions</a>
      <a href="blends.html">Concoctions</a>
      <a href="shop.html">Apothecary</a>
      <a href="contact.html">Connect</a>
    </nav>
  </header>

  <main class="wrap">
    <div class="grid">
      <section>
        <h2 style="margin:0 0 8px 0;color:var(--accent)">Curated items</h2>
